// Ported from the Node app's Sequelize model Supplier (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class SupplierConfiguration : IEntityTypeConfiguration<Supplier>
{
    public void Configure(EntityTypeBuilder<Supplier> builder)
    {
        builder.ToTable("suppliers");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.Name).HasColumnName("name").HasColumnType("nvarchar(120)").HasMaxLength(120).IsRequired();
        builder.Property(e => e.ContactPerson).HasColumnName("contact_person").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.Phone).HasColumnName("phone").HasColumnType("nvarchar(30)").HasMaxLength(30);
        builder.Property(e => e.Email).HasColumnName("email").HasColumnType("nvarchar(150)").HasMaxLength(150);
        builder.Property(e => e.Address).HasColumnName("address").HasColumnType("nvarchar(255)").HasMaxLength(255);
        builder.HasIndex(e => e.Name).IsUnique();
    }
}
